package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.util.*;
import org.junit.jupiter.api.*;

/** Real bounded native fingerprints; no final business permission is granted by this provider. */
class CatalogSourceFinalCommitFactsTest {
 CatalogSourceFinalArchiveTest f;JdbcCatalogSourceFinalCommitFacts service;
 GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
 void install(String category)throws Exception{f=new CatalogSourceFinalArchiveTest(){@Override GenerationJdbcStoreTest database(){return CatalogSourceFinalCommitFactsTest.this.database();}};f.install(category,2);f.f.complete();assertNotNull(f.service.stage(f.f.ref));service=new JdbcCatalogSourceFinalCommitFacts(f.f.f.source,category);}
 @BeforeEach void setup()throws Exception{install("agent");}
 List<String> roots(){return f.f.results.plan.chunks().stream().map(SourcePartitionPlanner.Chunk::rootId).toList();}
 JdbcCatalogSourceFinalCommitFacts.Snapshot capture(){return f.f.results.readonly(()->service.capture(f.f.ref.ownerId(),roots()));}
 @Test void fourCategoriesCaptureEveryOriginalNativeRecordWithoutBodyCopiesOrNewWrites()throws Exception{
  for(String category:List.of("agent","skill","workflow","model")){install(category);int count=f.f.f.count("1=1");var original=capture();assertEquals(category,original.category());assertEquals(f.f.ref.ownerId(),original.owner());assertTrue(original.rows().size()>10);assertTrue(original.rows().stream().allMatch(row->row.scalars().size()==35&&row.texts().size()==8));assertEquals(original,f.f.prepared.tx(()->service.lockAndRead(f.f.ref.ownerId(),roots())));assertEquals(count,f.f.f.count("1=1"));assertEquals(1,f.f.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertFalse(original.toString().contains("Fictional"));assertThrows(UnsupportedOperationException.class,()->original.rows().clear());}
 }
 @Test void changedFullBodyWithoutUpdatingItsStoredHashChangesTheNativeFingerprint(){
  var original=capture();String id=f.f.f.jdbc.queryForObject("SELECT id FROM jobs WHERE purpose='result' AND owner_job_id=? AND part_no=1",String.class,f.f.ref.ownerId());String body=f.f.f.jdbc.queryForObject("SELECT payload_json FROM jobs WHERE id=?",String.class,id);byte[] hash=f.f.f.jdbc.queryForObject("SELECT payload_hash FROM jobs WHERE id=?",byte[].class,id);var forged=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(body);String base=forged.path("bytes_base64").asText();forged.put("bytes_base64",(base.startsWith("A")?"B":"A")+base.substring(1));f.f.f.jdbc.update("UPDATE jobs SET payload_json=? WHERE id=?",JdbcFrozenInputs.canonical(forged),id);assertArrayEquals(hash,f.f.f.jdbc.queryForObject("SELECT payload_hash FROM jobs WHERE id=?",byte[].class,id));var changed=capture();var before=original.rows().stream().filter(row->id.equals(row.scalars().getFirst())).findFirst().orElseThrow().texts().getFirst();var after=changed.rows().stream().filter(row->id.equals(row.scalars().getFirst())).findFirst().orElseThrow().texts().getFirst();assertEquals(before.bytes(),after.bytes());assertNotEquals(before.hash(),after.hash());String actual=f.f.f.jdbc.queryForObject("SELECT payload_json FROM jobs WHERE id=?",String.class,id);try{assertEquals(HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(actual.getBytes(java.nio.charset.StandardCharsets.UTF_8))),after.hash());}catch(java.security.NoSuchAlgorithmException unavailable){throw new AssertionError(unavailable);}assertNotEquals(original,changed);f.f.f.jdbc.update("UPDATE jobs SET payload_json=? WHERE id=?",body,id);assertEquals(original,capture());
 }
 @Test void rehashedOriginalCollectionAndNativeRoleOrRevisionChangesAreCaptured(){
  var original=capture();String id=f.f.prepared.collection.dispositionId();String body=f.f.f.jdbc.queryForObject("SELECT action_payload FROM jobs WHERE id=?",String.class,id);byte[] hash=f.f.f.jdbc.queryForObject("SELECT action_payload_hash FROM jobs WHERE id=?",byte[].class,id);var changed=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(body);((tools.jackson.databind.node.ObjectNode)changed.get("facts")).put("manifestHash","b".repeat(64));String raw=JdbcFrozenInputs.canonical(changed);f.f.f.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",raw,JdbcGenerationLineage.hash(raw),id);assertNotEquals(original,capture());f.f.f.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",body,hash,id);assertEquals(original,capture());f.f.f.jdbc.update("UPDATE jobs SET operator_id='fictional-other' WHERE id=?",id);assertNotEquals(original,capture());f.f.f.jdbc.update("UPDATE jobs SET operator_id='collection-worker' WHERE id=?",id);f.f.f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",roots().getFirst());assertNotEquals(original,capture());
 }
 @Test void unexpectedRelatedRecordOrMissingOriginalPartCannotEqualCapturedSet(){
  var original=capture();f.f.prepared.tx(()->new JdbcJobRecords(f.f.f.source).putPart(new JdbcJobRecords.Part("fictional-extra-related",f.f.ref.ownerId(),"result","fictional-extra-stamp",0,"{}",CanonicalJson.hash(CanonicalJson.Domain.INPUT_PART,CanonicalJson.parse("{}"))),f.f.f.clock.instant()));assertNotEquals(original,capture());f.f.f.jdbc.update("DELETE FROM jobs WHERE id='fictional-extra-related'");assertEquals(original,capture());f.f.f.jdbc.update("DELETE FROM jobs WHERE purpose='result' AND owner_job_id=? AND part_no=1",f.f.ref.ownerId());assertNotEquals(original,capture());
 }
 @Test void nativeWriterChangeCanBeDetectedAndRolledBackBeforeAnyFinalReceipt(){
  var original=capture();String id=f.f.prepared.collection.dispositionId();assertThrows(RuntimeException.class,()->f.f.prepared.tx(()->{f.f.f.jdbc.update("UPDATE jobs SET operator_id='fictional-changed-inside-writer' WHERE id=?",id);if(!original.equals(service.lockAndRead(f.f.ref.ownerId(),roots())))throw new IllegalStateException("fictional native fingerprint mismatch");return true;}));assertEquals(original,capture());assertEquals(0,f.f.f.count("target_type='catalog_source_final_result'"));assertThrows(RuntimeException.class,()->f.f.prepared.tx(()->{f.f.f.jdbc.update("UPDATE jobs SET task_type='skill_dedup' WHERE id=?",f.f.ref.ownerId());return service.lockAndRead(f.f.ref.ownerId(),roots());}));assertEquals(original,capture());
 }
 @Test void nativeLargeBodyAnd100RootScopeAreBoundedBeforeReturningFacts(){
  String id=f.f.f.jdbc.queryForObject("SELECT id FROM jobs WHERE purpose='result' AND owner_job_id=? AND part_no=1",String.class,f.f.ref.ownerId());f.f.f.jdbc.update("UPDATE jobs SET payload_json=? WHERE id=?","{\"fictional_padding\":\""+"x".repeat(524289)+"\"}",id);assertThrows(JdbcCatalogSourceFinalCommitFacts.CapacityRejected.class,this::capture);var tooMany=new ArrayList<String>();for(int n=0;n<101;n++)tooMany.add(String.format(Locale.ROOT,"%064x",n));assertThrows(JdbcCatalogSourceFinalCommitFacts.CapacityRejected.class,()->f.f.results.readonly(()->service.capture(f.f.ref.ownerId(),tooMany)));
 }
 @Test void actual100NativeHeadersCanBeCapturedButRemainOnlyMetadata(){
  var plan=f.f.results.plan;var all=new ArrayList<String>(roots());for(int n=1;n<100;n++){int part=n;String id=JdbcFrozenInputs.stableId("fictional-native-fact-root",f.f.ref.ownerId()+":"+part);f.f.prepared.tx(()->new JdbcJobRecords(f.f.f.source).createRoot(new JdbcJobRecords.Root(id,f.f.ref.ownerId(),plan.logicalKey(),plan.generation(),part,"agent_dedup",plan.stage().priority()),f.f.f.clock.instant()));all.add(id);}var original=f.f.results.readonly(()->service.capture(f.f.ref.ownerId(),all));assertEquals(100,original.roots().size());assertEquals(original,f.f.prepared.tx(()->service.lockAndRead(f.f.ref.ownerId(),all)));assertEquals(0,f.f.f.count("target_type='catalog_source_final_result'"));assertEquals(1,f.f.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));
 }
 @Test void actualNativeAggregateByteBudgetRejectsCompleteLargeRelatedSet(){
  String owner=f.f.ref.ownerId(),template=f.f.f.jdbc.queryForObject("SELECT id FROM jobs WHERE purpose='result' AND owner_job_id=? AND part_no=1",String.class,owner);String body=JdbcFrozenInputs.canonical(tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("fictional_padding","x".repeat(300000)));byte[] hash=HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.INPUT_PART,CanonicalJson.parse(body)));
  // Explicit fictional raw-record setup outside the business writer; no final permission is claimed.
  for(int n=0;n<450;n++){String id=JdbcFrozenInputs.stableId("fictional-replay-capacity",owner+":"+n);assertEquals(1,f.f.f.jdbc.update("INSERT INTO jobs(id,business_key,task_kind,target_id,state,priority_no,eligible_at,revision,created_at,updated_at,record_kind,record_identity_hash,call_count,owner_job_id,purpose,stamp_id,part_no,payload_json,payload_hash) SELECT ?,?,'fixture',?,'stored',0,eligible_at,0,created_at,updated_at,'snapshot_part',?,0,owner_job_id,'result','fictional-replay-capacity',?,?,? FROM jobs WHERE id=?",id,"fictional-replay-capacity:"+n,id,HexFormat.of().parseHex(JdbcFrozenInputs.stableId("fictional-replay-record-identity",id)),n,body,hash,template));}
  assertThrows(JdbcCatalogSourceFinalCommitFacts.CapacityRejected.class,this::capture);assertEquals(450,f.f.f.count("stamp_id='fictional-replay-capacity'"));assertEquals(0,f.f.f.count("target_type='catalog_source_final_result'"));
 }
 @Test void exactOwnerRootIdentityAndTransactionRolesAreRequiredWithoutConstructorIo(){
  assertThrows(RuntimeException.class,()->service.capture(f.f.ref.ownerId(),roots()));assertThrows(RuntimeException.class,()->f.f.prepared.tx(()->service.capture(f.f.ref.ownerId(),roots())));assertThrows(RuntimeException.class,()->f.f.results.readonly(()->service.lockAndRead(f.f.ref.ownerId(),roots())));assertThrows(RuntimeException.class,()->f.f.results.readonly(()->service.capture(f.f.ref.ownerId().toUpperCase(Locale.ROOT),roots())));assertThrows(RuntimeException.class,()->f.f.results.readonly(()->service.capture(f.f.ref.ownerId(),List.of(roots().getFirst(),roots().getFirst()))));assertThrows(RuntimeException.class,()->f.f.results.readonly(()->service.capture(f.f.ref.ownerId(),List.of("b".repeat(64)))));var other=new JdbcCatalogSourceFinalCommitFacts(f.f.f.source,"model");assertThrows(RuntimeException.class,()->f.f.results.readonly(()->other.capture(f.f.ref.ownerId(),roots())));var source=org.mockito.Mockito.mock(javax.sql.DataSource.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new JdbcCatalogSourceFinalCommitFacts(source,category));for(String category:List.of("news_tech","AGENT","report",""))assertThrows(RuntimeException.class,()->new JdbcCatalogSourceFinalCommitFacts(source,category));org.mockito.Mockito.verifyNoInteractions(source);
 }
}
